import {analyze,report,csv} from './core.js';import {readEvidence} from './input.js';import {samples} from './fixtures.js';import {AUDIO_SHA256} from './audio-fixture.js';
const $=id=>document.getElementById(id);let items=[],selected=0,offset=0,busy=false,lastExport=null,audioUrl=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function download(data,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function load(files,origin){if(busy)return;busy=true;$('message').textContent='Analyzing locally…';try{if(files.length>20||files.some(f=>(f.size??f.bytes.length)>20*1024**2)||files.reduce((n,f)=>n+(f.size??f.bytes.length),0)>100*1024**2)throw Error('Batch limit exceeded. Choose at most 20 files, 20 MiB each, 100 MiB total.');const next=[];for(const f of files)next.push(await analyze(f.name,await readEvidence(f),origin));items=next;selected=0;offset=0;$('filter').value='All';render();$('message').textContent=`${items.length} files analyzed. Previous batch replaced. No files were uploaded.`;}catch(e){$('message').textContent=e.message;}finally{busy=false;}}
$('choose-files').onclick=()=>{if(!busy)$('files').click();};$('files').onchange=e=>load([...e.target.files],'user upload');$('demo').onclick=async()=>{lastExport=null;await load([{name:'MyCAT.jpg',bytes:samples()[0].bytes}],'MyCAT preset / synthetic test / generated 2026');$('detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('resulttitle')?.focus({preventScroll:true});};$('audio-demo').onclick=async()=>{lastExport=null;await load([{name:'File05-synthetic',bytes:samples()[1].bytes}],'Audio preset / new synthetic two-tone sample');$('detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('resulttitle')?.focus({preventScroll:true});};$('clear').onclick=()=>{if(busy)return;items=[];selected=0;lastExport=null;render();$('files').value='';$('message').textContent='Session cleared.';};$('filter').onchange=queue;
function queue(){const q=$('queue');q.replaceChildren();items.forEach((r,i)=>{if($('filter').value!=='All'&&$('filter').value!==r.status)return;const b=document.createElement('button');b.className='evidence'+(selected===i?' active':'');b.innerHTML=esc(r.name)+'<small>'+esc(r.detection.type+' · '+r.explanation.label)+'</small>';b.onclick=()=>{selected=i;offset=0;render();};q.append(b);});}
function render(){if(audioUrl){$('audioplayer')?.pause();URL.revokeObjectURL(audioUrl);audioUrl=null;}queue();const counts={};for(const r of items)counts[r.status]=(counts[r.status]||0)+1;$('metrics').innerHTML=[['FILES',items.length],['MISMATCHES',counts.Mismatch||0],['MISSING EXT.',counts['Missing extension']||0],['UNCONFIRMED',counts.Unknown||0]].map(([l,n])=>`<div class="metric">${l}<strong>${n}</strong></div>`).join('');$('chart').innerHTML=Object.entries(counts).map(([k,n])=>`<div class="chartrow"><span>${k==='Unknown'?'Unconfirmed':k}</span><div><div class="bar" style="width:${n/Math.max(items.length,1)*100}%"></div></div><span>${n}</span></div>`).join('')||'<p>No batch data yet.</p>';
const r=items[selected];$('hexcontrols').hidden=!r;if(!r){$('detail').innerHTML='<h3>No evidence selected</h3><p>Upload files or load the reproducible synthetic experiments.</p>';$('hex').replaceChildren();return;}
const d=r.detection,e=r.explanation;
const verified=lastExport&&r.sha256===lastExport.hash;
$('detail').innerHTML=`<p class="eyebrow">${esc(r.origin)}</p><h3 id="resulttitle" tabindex="-1">${esc(r.name)}</h3><div class="casejourney" aria-label="Investigation steps"><div><span>01 / FILENAME</span><strong>${esc(e.filenameClaim)}</strong></div><div><span>02 / SIGNATURE</span><strong>${esc(d.type==='Unknown'?'Unconfirmed':d.type)}</strong></div><div><span>03 / PRESERVE</span><strong>${verified?'Same content verified':r.recoveredName?'Export a separate copy':'Keep original for review'}</strong></div></div><div class="typecompare"><div><span>FILENAME CLAIMS</span><strong>${esc(e.filenameClaim)}</strong><p>The extension is the suffix in the filename.</p></div><div><span>SIGNATURE INDICATES</span><strong>${esc(d.type==='Unknown'?'Unconfirmed':d.type)}</strong><p>The detector compares content bytes with supported format rules, not with another uploaded file.</p></div></div><div class="finding ${r.status==='Mismatch'?'anomaly':''}"><strong>${esc(e.label)}</strong><p>${esc(e.reason)}</p>${r.status==='Mismatch'?'<p class="takeaway">A filename can change while the content stays the same.</p>':''}</div><details class="reasoning" open><summary>Why this result?</summary><p>${esc(e.signatureReason)}</p><dl><dt>Observed ${d.headerOffset===null?'opening bytes':'header bytes'} · offset ${d.headerOffset??0}</dt><dd><code>${esc(e.observedHeader)}</code></dd>${e.expectedHeader?'<dt>Expected for the filename extension</dt><dd><code>'+esc(e.expectedHeader)+'</code></dd>':''}<dt>Signature rule / format</dt><dd>${esc(d.type)} · ${esc(d.confidence)}</dd></dl><p>${esc(e.scope)}</p></details><p>${r.size.toLocaleString()} bytes · Header offset: ${d.headerOffset??'not found'} · Trailer offset: ${d.trailerOffset??'not found / not defined'}.</p>${d.audio?`<p>MPEG frame metadata: ${d.audio.sampleRate} Hz · ${d.audio.channels} channel(s). Frame-header detection does not validate audio playback.</p>`:''}<p class="orange">${d.warnings.map(esc).join(' ')}</p>${r.sha256===AUDIO_SHA256?'<div class="audio-preview"><p class="eyebrow">NEW SYNTHETIC AUDIO / SAFE DEMO</p><h4>Hear the evidence</h4><p>Two soft tones: 440 Hz, then 660 Hz. About 2.4 seconds of generated audio, 44.1 kHz stereo. No voice, music or personal recording. This is not the historical File05.</p><audio id="audioplayer" controls preload="metadata" aria-label="Synthetic two-tone MP3 preview"></audio><button id="playaudio">Play synthetic audio</button><p id="audiostatus" role="status">Ready to play. The missing extension does not remove the encoded audio.</p></div>':''}<div class="hash"><strong>SHA-256 / content fingerprint</strong><p>Compare this fingerprint with a copy to check whether its content is identical.</p>${r.sha256}</div><div class="copycheck" role="status">${lastExport?(verified?'✓ Same SHA-256 as the last copy prepared for download. The content matches.':'This file has a different SHA-256 from the last copy prepared for download.'):'After downloading a copy, upload it again to compare its SHA-256 with this source.'}</div><p>A new extension helps compatible apps recognize the file. It does not repair damaged content or change the bytes.</p>${r.recoveredName?'<button id="recover">Download a copy with the correct extension</button><p class="copyname">Suggested filename: '+esc(r.recoveredName)+'</p>':'<p>No confident extension suggestion available. Preserve the original and investigate further.</p>'}`;
if(r.sha256===AUDIO_SHA256){
 const player=$('audioplayer'),play=$('playaudio'),status=$('audiostatus');audioUrl=URL.createObjectURL(new Blob([r.bytes],{type:'audio/mpeg'}));player.src=audioUrl;player.volume=.35;
 player.onloadedmetadata=()=>{if(!player.paused)return;status.textContent='Ready to play · '+player.duration.toFixed(2)+' seconds decoded. No extension is needed to identify the audio bytes.';};
 player.onplay=()=>{play.textContent='Pause synthetic audio';status.textContent='Playing the generated two-tone MP3.';};
 player.onpause=()=>{play.textContent='Play synthetic audio';if(!player.ended)status.textContent='Playback paused.';};
 player.onended=()=>{play.textContent='Play synthetic audio';status.textContent='Playback complete · '+player.duration.toFixed(2)+' seconds. Renaming the file does not change its playable audio content.';};
 player.onerror=()=>{status.textContent='This browser could not decode the bundled MP3. Detection results remain available.';};
 play.onclick=async()=>{try{if(player.paused){if(player.ended)player.currentTime=0;await player.play();}else player.pause();}catch{status.textContent='Playback could not start. Use the native audio controls or try another browser.';}};
}
if(r.recoveredName)$('recover').onclick=()=>{lastExport={hash:r.sha256,name:r.name};download(r.bytes,r.recoveredName);$('message').textContent='Copy prepared for download. Re-upload the saved copy to verify its SHA-256.';render();};drawHex();}

function drawHex(){const r=items[selected];if(!r)return;offset=Math.max(0,Math.min(Math.floor(offset/16)*16,Math.max(0,Math.floor((r.size-1)/16)*16)));$('offset').value='0x'+offset.toString(16);const d=r.detection;let html='';for(let i=offset;i<Math.min(offset+256,r.size);i+=16){html+=`<div><span class="addr">${i.toString(16).padStart(8,'0')}</span>`;for(let j=i;j<Math.min(i+16,r.size);j++){const h=d.headerOffset!==null&&j>=d.headerOffset&&j<d.headerOffset+d.headerLength;const t=d.trailerOffset!==null&&j>=d.trailerOffset&&j<d.trailerOffset+(d.trailer?.length||0)/2;html+=`<button class="${h?'h':t?'t':''}" data-byte="${j}" aria-label="Byte ${j}, hexadecimal ${r.bytes[j].toString(16)}">${r.bytes[j].toString(16).padStart(2,'0')}</button> `;}html+='<span class="ascii">'+esc(Array.from(r.bytes.subarray(i,i+16),v=>v>=32&&v<=126?String.fromCharCode(v):'.').join(''))+'</span></div>';}$('hex').innerHTML=html||'Empty file';$('byteinfo').textContent='';$('hex').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('byteinfo').textContent=`Offset ${b.dataset.byte} (0x${Number(b.dataset.byte).toString(16)}), decimal value ${r.bytes[b.dataset.byte]}`;});}
$('go').onclick=()=>{const v=$('offset').value.trim();if(!/^(0x[0-9a-f]+|\d+)$/i.test(v)||!Number.isSafeInteger(Number(v))){$('byteinfo').textContent='Enter a nonnegative decimal or hexadecimal offset.';return;}offset=Number(v);drawHex();};$('prev').onclick=()=>{offset-=256;drawHex();};$('next').onclick=()=>{offset+=256;drawHex();};$('headerjump').onclick=()=>{offset=items[selected].detection.headerOffset??0;drawHex();};$('trailerjump').onclick=()=>{const n=items[selected].detection.trailerOffset;if(n===null){$('byteinfo').textContent='No trailer found or defined for this format.';return;}offset=n;drawHex();};
function getReport(){return report(items,$('case').value,$('notes').value);}
$('json').onclick=()=>download(JSON.stringify(getReport(),null,2),'investigation.json','application/json');$('csv').onclick=()=>download(csv(items),'investigation.csv','text/csv');$('htmlreport').onclick=()=>{const r=getReport();download(`<!doctype html><meta charset="utf-8"><title>Investigation report</title><style>body{font:14px/1.6 system-ui;max-width:900px;margin:40px auto;padding:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{break-inside:avoid;border-top:1px solid #ccc} @media print{button{display:none}}</style><h1>${esc(r.caseName)}</h1><p>${esc(r.createdAt)}</p><p>${esc(r.method)}</p><p>${esc(r.sourceLimit)}</p><pre>${esc(r.notes)}</pre>${r.results.map(x=>'<article><h2>'+esc(x.name)+'</h2><pre>'+esc(JSON.stringify(x,null,2))+'</pre></article>').join('')}<p>Use your browser Print menu to save this report as PDF.</p>`,'investigation-report.html','text/html');};
const originals=['Demo1_5_Go to the website.jpg','Demo1_6_Find Header & Trailers.jpg','Demo1_7_File Trailer.jpg','Demo1_8_Adding Extension.jpg','Demo1_9_It works.jpg','Demo2_1_File without extension.jpg','Demo2_2_Find Extension.jpg','Demo2_3_Edit Extension.jpg','Demo2_4_File Extension Works.jpg'];$('gallery').innerHTML=originals.map(n=>`<figure><a href="public/originals/${encodeURIComponent(n)}" target="_blank" rel="noopener"><img loading="lazy" src="public/originals/${encodeURIComponent(n)}" alt="Historical original: ${esc(n)}"></a><figcaption>ORIGINAL SCREENSHOT · ${esc(n)}</figcaption></figure>`).join('');render();




